mapper.select:
SELECT order_price AS price, SUM(remaining_token) AS totalVolume, 'BUY' AS side FROM orders WHERE token_id = #{tokenId} AND order_side = 'BUY'::order_side_enum AND order_state IN ('NEW'::order_state_enum, 'PARTIAL'::order_state_enum) AND order_type = 'LIMIT'::order_type_enum
AND order_price >= #{price}
GROUP BY order_price ORDER BY order_price ASC LIMIT 20

SELECT order_price AS price, SUM(remaining_token) AS totalVolume, 'SELL' AS side FROM orders WHERE token_id = #{tokenId} AND order_side = 'SELL'::order_side_enum AND order_state IN ('NEW'::order_state_enum, 'PARTIAL'::order_state_enum) AND order_type = 'LIMIT'::order_type_enum
AND order_price <= #{price}
GROUP BY order_price ORDER BY order_price DESC LIMIT 20
